provides Keys = ClientKeys {
    fn forget(id: AccountId, key: ApiKeyId) -> Effect[Bool] {
        Client.revoke(id, key)   // ✗ in a provider
    }
}

on DELETE("/accounts/:id/keys/:key") (id: AccountId, key: ApiKeyId) -> Effect[HttpResult[()]] by Visitor {
    let gone <- Client.revoke(id, key)   // ✓ in a service handler
    if gone { NoContent } else { NotFound }
}
